const COURSE_LESSON_HTML = {
  "kurssArticlesLesson": "\n  <h3>Greinir</h3>\n\n  <div class=\"artikuli-info artikuli-intro-info\">\n    <span class=\"artikuli-info-icon\">i</span>\n    <div>Þýski greinirinn passar ekki alltaf við kyn orðsins á íslensku. Þess vegna er best að læra nafnorð ásamt greininum.</div>\n  </div>\n\n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>•</span>Dæmi um greini</h4>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">der Tisch — borð</div>\n      <div class=\"kurss-example\">die Tür — hurð</div>\n      <div class=\"kurss-example\">das Messer — hnífur</div>\n      <div class=\"kurss-example\">das Mädchen — stúlka</div>\n    </div>\n  </section>\n\n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>♂</span>Oft DER</h4>\n    <p class=\"artikuli-explain\">DER er oft notað um karlkyns persónur, daga, mánuði, árstíðir og sum orð með ákveðnum endingum.</p>\n\n    <h5 class=\"artikuli-subtitle\">Reglur</h5>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">-er → oft DER, til dæmis: der Computer, der Lehrer <span class=\"artikuli-note\">en ekki alltaf</span></div>\n      <div class=\"kurss-example\">-ling → oft DER, til dæmis: der Schmetterling</div>\n      <div class=\"kurss-example\">-ismus → oft DER, til dæmis: der Tourismus, der Kapitalismus</div>\n      <div class=\"kurss-example\">karlkyns persónur → der Mann, der Vater</div>\n      <div class=\"kurss-example\">starfsheiti → der Lehrer, der Arzt</div>\n      <div class=\"kurss-example\">bílategundir → der BMW, der Mercedes</div>\n      <div class=\"kurss-example\">dagar → der Montag, der Dienstag</div>\n      <div class=\"kurss-example\">mánuðir → der August, der Dezember</div>\n      <div class=\"kurss-example\">árstíðir → der Sommer, der Winter</div>\n    </div>\n\n    <h5 class=\"artikuli-subtitle\">Dæmi</h5>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">der Mann — karlmaður</div>\n      <div class=\"kurss-example\">der Vater — faðir</div>\n      <div class=\"kurss-example\">der Montag — mánudagur</div>\n      <div class=\"kurss-example\">der August — ágúst</div>\n      <div class=\"kurss-example\">der Sommer — sumar</div>\n      <div class=\"kurss-example\">der Lehrer — kennari</div>\n      <div class=\"kurss-example\">der Computer — tölva</div>\n      <div class=\"kurss-example\">der Schmetterling — fiðrildi</div>\n    </div>\n  </section>\n\n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>♀</span>Oft DIE</h4>\n    <p class=\"artikuli-explain\">DIE er oft notað um kvenkyns persónur, fleirtölu og orð með endingunum -ung, -heit, -keit, -schaft, -ion, -tät, -ei.</p>\n\n    <h5 class=\"artikuli-subtitle\">Reglur</h5>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">-ung → die Wohnung, die Rechnung</div>\n      <div class=\"kurss-example\">-heit → die Freiheit, die Gesundheit</div>\n      <div class=\"kurss-example\">-keit → die Möglichkeit</div>\n      <div class=\"kurss-example\">-schaft → die Mannschaft</div>\n      <div class=\"kurss-example\">-ion → die Nation</div>\n      <div class=\"kurss-example\">-tät → die Universität</div>\n      <div class=\"kurss-example\">-ei → die Polizei, die Bäckerei</div>\n      <div class=\"kurss-example\">kvenkyns persónur → die Frau, die Mutter</div>\n      <div class=\"kurss-example\">mótorhjólategundir → die Harley-Davidson, die Yamaha</div>\n      <div class=\"kurss-example\">fleirtala → die Autos, die Häuser</div>\n      <div class=\"kurss-example\">fleirtala nær alltaf → die Autos, die Häuser, die Kinder</div>\n    </div>\n\n    <h5 class=\"artikuli-subtitle\">Dæmi</h5>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">die Frau — kona</div>\n      <div class=\"kurss-example\">die Mutter — móðir</div>\n      <div class=\"kurss-example\">die Wohnung — íbúð</div>\n      <div class=\"kurss-example\">die Rechnung — reikningur</div>\n      <div class=\"kurss-example\">die Freiheit — frelsi</div>\n      <div class=\"kurss-example\">die Möglichkeit — möguleiki</div>\n      <div class=\"kurss-example\">die Mannschaft — lið</div>\n      <div class=\"kurss-example\">die Nation — þjóð</div>\n      <div class=\"kurss-example\">die Universität — háskóli</div>\n      <div class=\"kurss-example\">die Polizei — lögregla</div>\n    </div>\n  </section>\n\n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>◇</span>Oft DAS</h4>\n    <p class=\"artikuli-explain\">DAS er oft notað um smækkunarorð með -chen / -lein, mörg orð með -ment / -um og sagnir sem notaðar eru sem nafnorð.</p>\n\n    <h5 class=\"artikuli-subtitle\">Reglur</h5>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">-chen → das Mädchen, das Häuschen</div>\n      <div class=\"kurss-example\">-lein → das Fräulein</div>\n      <div class=\"kurss-example\">-ment → das Instrument</div>\n      <div class=\"kurss-example\">-um → das Zentrum, das Museum</div>\n      <div class=\"kurss-example\">málmar → das Gold, das Silber, das Eisen</div>\n      <div class=\"kurss-example\">frumefni → das Eisen, das Kupfer</div>\n      <div class=\"kurss-example\">hótel → das Hotel</div>\n      <div class=\"kurss-example\">litir sem nafnorð → das Rot, das Blau</div>\n      <div class=\"kurss-example\">sögn sem nafnorð → das Essen, das Lernen</div>\n      <div class=\"kurss-example\">sagnir sem nafnorð → das Essen, das Lernen, das Lesen</div>\n    </div>\n\n    <h5 class=\"artikuli-subtitle\">Dæmi</h5>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">das Kind — barn</div>\n      <div class=\"kurss-example\">das Mädchen — stúlka</div>\n      <div class=\"kurss-example\">das Häuschen — lítið hús</div>\n      <div class=\"kurss-example\">das Instrument — hljóðfæri</div>\n      <div class=\"kurss-example\">das Zentrum — miðja</div>\n      <div class=\"kurss-example\">das Museum — safn</div>\n      <div class=\"kurss-example\">das Essen — að borða / matur</div>\n      <div class=\"kurss-example\">das Lernen — nám</div>\n    </div>\n  </section>\n\n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>!</span>Mikilvægar undantekningar / læra þarf með greini</h4>\n    <p class=\"artikuli-explain\">Fyrir sum orð er ekki hægt að ákvarða greininn með vissu út frá endingunni eða kyni orðsins á íslensku. Best er að læra þau ásamt greininum.</p>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">die Tür — hurð</div>\n      <div class=\"kurss-example\">das Messer — hnífur</div>\n      <div class=\"kurss-example\">die Sonne — sól</div>\n      <div class=\"kurss-example\">der Mond — tungl</div>\n      <div class=\"kurss-example\">das Mädchen — stúlka</div>\n      <div class=\"kurss-example\">das Auto — bíll</div>\n      <div class=\"kurss-example\">der Käse — ostur</div>\n      <div class=\"kurss-example\">die Gabel — gaffall</div>\n    </div>\n  </section>\n\n  <div class=\"artikuli-info artikuli-bottom-info\">\n    <span class=\"artikuli-info-icon\">i</span>\n    <div>Endingar og orðahópar hjálpa til við að giska á greininn, en þær eru ekki 100% örugg regla. Ef þú ert ekki viss skaltu læra orðið ásamt greininum.</div>\n  </div>\n",
  "kurssPronounsLesson": "\n  <h3>Fornöfn</h3>\n            <div class=\"artikuli-info artikuli-intro-info\">\n    <span class=\"artikuli-info-icon\">i</span>\n    <div>Nominativ, Akkusativ og Dativ — form fornafna.</div>\n  </div>\n\n            \n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>N</span>Nominativ — hver?</h4>\n    <div class=\"artikuli-grid\"><div class=\"kurss-example\">ich — ég</div><div class=\"kurss-example\">du — þú</div><div class=\"kurss-example\">er — hann</div><div class=\"kurss-example\">sie — hún</div><div class=\"kurss-example\">es — það</div><div class=\"kurss-example\">wir — við</div><div class=\"kurss-example\">ihr — þið</div><div class=\"kurss-example\">sie — þeir / þær / þau</div><div class=\"kurss-example\">Sie — þér (formlegt)</div></div>\n  </section>\n\n            \n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>A</span>Akkusativ — hvern?</h4>\n    <div class=\"artikuli-grid\"><div class=\"kurss-example\">mich — mig</div><div class=\"kurss-example\">dich — þig</div><div class=\"kurss-example\">ihn — hann (kk.)</div><div class=\"kurss-example\">sie — hana (kvk.)</div><div class=\"kurss-example\">es — það</div><div class=\"kurss-example\">uns — okkur</div><div class=\"kurss-example\">euch — ykkur</div><div class=\"kurss-example\">sie — þá / þær / þau</div><div class=\"kurss-example\">Sie — yður (formlegt)</div></div>\n  </section>\n\n            \n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>D</span>Dativ — hverjum?</h4>\n    <div class=\"artikuli-grid\"><div class=\"kurss-example\">mir — mér</div><div class=\"kurss-example\">dir — þér</div><div class=\"kurss-example\">ihm — honum / því</div><div class=\"kurss-example\">ihr — henni</div><div class=\"kurss-example\">uns — okkur</div><div class=\"kurss-example\">euch — ykkur</div><div class=\"kurss-example\">ihnen — þeim</div><div class=\"kurss-example\">Ihnen — yður (formlegt)</div></div>\n  </section>\n\n            \n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>?</span>Hvernig á að velja formið?</h4>\n    <ul class=\"kurss-summary-list\"><li><span class=\"case-blue\">Nominativ</span> — frumlag (hver gerir?)</li><li><span class=\"case-red\">Akkusativ</span> — beint andlag (hvern?)</li><li><span class=\"case-green\">Dativ</span> — óbeint andlag (hverjum?)</li></ul>\n  </section>\n\n            \n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>•</span>Dæmi</h4>\n    <div class=\"artikuli-grid\"><div class=\"kurss-example\">Ich sehe <span class=\"case-red\">dich</span>. — Ég sé þig.</div><div class=\"kurss-example\">Ich sehe <span class=\"case-red\">ihn</span>. — Ég sé hann.</div><div class=\"kurss-example\">Wir mögen <span class=\"case-red\">euch</span>. — Okkur líkar vel við ykkur.</div><div class=\"kurss-example\">Ich helfe <span class=\"case-green\">dir</span>. — Ég hjálpa þér.</div><div class=\"kurss-example\">Ich gebe <span class=\"case-green\">ihm</span> ein Buch. — Ég gef honum bók.</div><div class=\"kurss-example\">Wir danken <span class=\"case-green\">euch</span>. — Við þökkum ykkur.</div></div>\n  </section>\n\n  <div class=\"artikuli-info artikuli-bottom-info\">\n    <span class=\"artikuli-info-icon\">i</span>\n    <div>Nominativ er alltaf frumlag setningarinnar, en Akkusativ og Dativ eru andlög. Horfðu á sögnina og spyrðu: <span class=\"case-red\">hvern?</span> eða <span class=\"case-green\">hverjum?</span></div>\n  </div>\n",
  "kurssPronunciationLesson": "\n            <h3>Sérhljóð — löng og stutt</h3>\n            <div class=\"artikuli-info artikuli-intro-info\">\n              <span class=\"artikuli-info-icon\">i</span>\n              <div>Í þýsku geta sérhljóð verið löng eða stutt. Það hefur áhrif á framburð orðsins.</div>\n            </div>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>Langt sérhljóð</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">warm (varm) — hlýr</div><div class=\"kurss-example\">gut (gút) — góður</div><div class=\"kurss-example\">Tat (tāt) — dáð / verk</div><div class=\"kurss-example\">Flur (flúr) — gangur / forstofa</div><div class=\"kurss-example\">Weg (vēk) — vegur / leið</div><div class=\"kurss-example\">Hut (hút) — hattur</div><div class=\"kurss-example\">Hof (hōf) — húsagarður / bær</div><div class=\"kurss-example\">Schlaf (sjlāf) — svefn</div></div>\n              <p class=\"artikuli-explain\">Ef eitt samhljóð fer á eftir sérhljóði er sérhljóðið oft borið fram langt.</p>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>Stutt sérhljóð</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">Pilz (pilts) — sveppur</div><div class=\"kurss-example\">Wort (vort) — orð</div><div class=\"kurss-example\">Mund (múnt) — munnur</div><div class=\"kurss-example\">bald (balt) — bráðum</div><div class=\"kurss-example\">scharf (sjarf) — beittur / sterkur (á bragðið)</div><div class=\"kurss-example\">Feld (felt) — akur / völlur</div><div class=\"kurss-example\">voll (fol) — fullur</div></div>\n              <p class=\"artikuli-explain\">Ef tvö eða fleiri samhljóð fara á eftir sérhljóði er sérhljóðið oft borið fram stutt.</p>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>Endingarnar en / el / er</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">singen (zingen) — syngja</div><div class=\"kurss-example\">tragen (trāgen) — bera</div><div class=\"kurss-example\">Garten (garten) — garður</div><div class=\"kurss-example\">Vogel (fōgel) — fugl</div><div class=\"kurss-example\">Segel (zēgel) — segl</div><div class=\"kurss-example\">Braten (brāten) — steik</div><div class=\"kurss-example\">Bogen (bōgen) — bogi</div><div class=\"kurss-example\">Spiegel (sjpígel) — spegill</div><div class=\"kurss-example\">Finger (finger) — fingur</div><div class=\"kurss-example\">Halter (halter) — haldari / festing</div><div class=\"kurss-example\">Arbeiter (arbæter) — verkamaður</div><div class=\"kurss-example\">Häuser (hojzer) — hús (ft.)</div><div class=\"kurss-example\">wieder (víder) — aftur</div><div class=\"kurss-example\">breiter (bræter) — breiðari</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>Bókstafurinn h sem lengdarmerki</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">Rahmen (rāmen) — rammi</div><div class=\"kurss-example\">Ohr (ōr) — eyra</div><div class=\"kurss-example\">Kohle (kōle) — kol</div><div class=\"kurss-example\">Zahl (tsāl) — tala</div><div class=\"kurss-example\">ihn (ín) — hann (þolfall)</div><div class=\"kurss-example\">ihm (ím) — honum</div><div class=\"kurss-example\">Huhn (hún) — hæna</div><div class=\"kurss-example\">nahm (nām) — tók</div><div class=\"kurss-example\">nehmen (nēmen) — taka</div><div class=\"kurss-example\">Schuh (sjú) — skór</div></div>\n              <p class=\"artikuli-explain\">Í sumum orðum lengir h sérhljóðið á undan. Í slíkum tilvikum er h yfirleitt ekki borið fram.</p>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>Endingar á e</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">Lampe (lampe) — lampi</div><div class=\"kurss-example\">Hase (hāze) — héri</div><div class=\"kurss-example\">Knabe (knābe) — drengur / piltur</div><div class=\"kurss-example\">Rabe (rābe) — hrafn</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>Langt i = ie</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">die (dí) — ákveðni greinirinn „die“</div><div class=\"kurss-example\">diese (díze) — þessi</div><div class=\"kurss-example\">wieder (víder) — aftur</div><div class=\"kurss-example\">Fliege (flíge) — fluga</div><div class=\"kurss-example\">Ziege (tsíge) — geit</div><div class=\"kurss-example\">Stiel (sjtíl) — stilkur / skaft</div><div class=\"kurss-example\">Dieb (díp) — þjófur</div><div class=\"kurss-example\">hier (hír) — hér</div></div>\n              <p class=\"artikuli-explain\">Langt i er oft skrifað ie í þýsku.</p>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>Tvöföld sérhljóð</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">Saal (zāl) — salur</div><div class=\"kurss-example\">Saat (zāt) — sáning / útsæði</div><div class=\"kurss-example\">Staat (sjtāt) — ríki</div><div class=\"kurss-example\">Beere (bēre) — ber</div><div class=\"kurss-example\">See (zē) — stöðuvatn / haf</div><div class=\"kurss-example\">Beet (bēt) — beð</div><div class=\"kurss-example\">Boot (bōt) — bátur</div><div class=\"kurss-example\">Moor (mōr) — mýri</div><div class=\"kurss-example\">Moos (mōs) — mosi</div></div>\n              <p class=\"artikuli-explain\">Tvöföld sérhljóð eru yfirleitt borin fram löng.</p>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>ä</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">Wand (vant) — veggur</div><div class=\"kurss-example\">Wände (vende) — veggir</div><div class=\"kurss-example\">Vater (fāter) — faðir</div><div class=\"kurss-example\">Väter (fēter) — feður</div><div class=\"kurss-example\">Schrank (sjrank) — skápur</div><div class=\"kurss-example\">Schränke (sjrenke) — skápar</div><div class=\"kurss-example\">Bank (bank) — bekkur / banki</div><div class=\"kurss-example\">Bänke (benke) — bekkir</div><div class=\"kurss-example\">Tal (tāl) — dalur</div><div class=\"kurss-example\">Täler (tēler) — dalir</div></div>\n              <p class=\"artikuli-explain\">ä er hljóðvarp af a.</p>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>ö</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">Rose (rōze) — rós</div><div class=\"kurss-example\">Röschen (rȫshjen) — lítil rós</div><div class=\"kurss-example\">Ofen (ōfen) — ofn</div><div class=\"kurss-example\">Öfen (ȫfen) — ofnar</div><div class=\"kurss-example\">Rock (rok) — pils</div><div class=\"kurss-example\">Röcke (röke) — pils (ft.)</div></div>\n              <p class=\"artikuli-explain\">ö er hljóðvarp af o.</p>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>ü</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">kurz (kúrts) — stuttur</div><div class=\"kurss-example\">kürzer (kurtser) — styttri</div><div class=\"kurss-example\">Kunst (kúnst) — list</div><div class=\"kurss-example\">Künste (kunste) — listir</div><div class=\"kurss-example\">Mutter (múter) — móðir</div><div class=\"kurss-example\">Mütter (muter) — mæður</div></div>\n              <p class=\"artikuli-explain\">ü er hljóðvarp af u.</p>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>Tvíhljóð: äu</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">Baum (bám) — tré</div><div class=\"kurss-example\">Bäume (bojme) — tré (ft.)</div><div class=\"kurss-example\">Haus (hás) — hús</div><div class=\"kurss-example\">Häuser (hojzer) — hús (ft.)</div><div class=\"kurss-example\">Strauch (sjtráh) — runni</div><div class=\"kurss-example\">Sträucher (sjtrojhjer) — runnar</div><div class=\"kurss-example\">Maus (más) — mús</div><div class=\"kurss-example\">Mäuse (mojze) — mýs</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>Tvíhljóð: eu</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">heute (hojte) — í dag</div><div class=\"kurss-example\">Leute (lojte) — fólk</div><div class=\"kurss-example\">neu (noj) — nýr</div><div class=\"kurss-example\">neun (nojn) — níu</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>Tvíhljóð: ei</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">mein (mæn) — minn</div><div class=\"kurss-example\">dein (dæn) — þinn</div><div class=\"kurss-example\">sein (zæn) — hans / vera</div><div class=\"kurss-example\">frei (fræ) — frjáls</div><div class=\"kurss-example\">arbeiten (arbæten) — vinna</div></div>\n            </section>\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>✓</span>Framburðarathugasemdir úr 2. kennslustund</h4>\n              <ul class=\"kurss-summary-list\"><li>í orðunum ich, nicht, rechnen, zeichnen er „ch“ borið fram mjúkt (líkt og hj í „hjá“)</li><li>í orðunum arbeiten og zeichnen er „ei“ borið fram eins og „æ“</li><li>„sp“ í upphafi orðs er borið fram eins og „sjp“</li><li>í sögninni tun er „u“ borið fram langt</li></ul>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>✓</span>Samantekt</h4>\n              <ul class=\"kurss-summary-list\"><li>eitt samhljóð á eftir sérhljóði → oft langt sérhljóð</li><li>tvö eða fleiri samhljóð → oft stutt sérhljóð</li><li>h getur lengt sérhljóð</li><li>ie táknar oft langt i</li><li>tvöföld sérhljóð eru yfirleitt löng</li></ul>\n            </section>",
  "kurssConsonantsLesson": "\n            <h3>Samhljóð og stafasambönd</h3>\n            <div class=\"artikuli-info artikuli-intro-info\">\n              <span class=\"artikuli-info-icon\">i</span>\n              <div>Í þýsku eru sum samhljóð og stafasambönd borin fram öðruvísi en þau eru skrifuð. Í þessari kennslustund eru mikilvægustu dæmin fyrir byrjendur.</div>\n            </div>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>Samhljóð</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">das Rad (das rāt) — hjól</div><div class=\"kurss-example\">die Räder (dí rēder) — hjól (ft.)</div><div class=\"kurss-example\">Bad (bāt) — bað / baðherbergi</div><div class=\"kurss-example\">Bäder (bēder) — böð / baðherbergi</div></div>\n              <p class=\"artikuli-explain\">Í enda orðs eru samhljóð oft ekki borin fram eins og þau eru skrifuð.</p>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>ch</h4>\n              <p class=\"artikuli-explain\">„ch“ getur verið borið fram mjúkt eða hart. Í sumum orðum hljómar það líkt og hj í „hjá“, í öðrum líkt og g í „sagt“.</p>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">rechnen (rehjnen) — reikna</div><div class=\"kurss-example\">zeichnen (tsæhjnen) — teikna</div><div class=\"kurss-example\">nicht (nihjt) — ekki</div><div class=\"kurss-example\">schlecht (sjlehjt) — slæmur</div><div class=\"kurss-example\">mich (mihj) — mig</div><div class=\"kurss-example\">dich (dihj) — þig</div><div class=\"kurss-example\">Strauch (sjtráh) — runni</div><div class=\"kurss-example\">noch (noh) — enn</div><div class=\"kurss-example\">Nacht (naht) — nótt</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>sch</h4>\n              <p class=\"artikuli-explain\">„sch“ er borið fram í þýsku eins og „sj“ í „sjampó“ (líkt og enska „sh“).</p>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">Schule (sjúle) — skóli</div><div class=\"kurss-example\">Schüler (sjūler) — nemandi</div><div class=\"kurss-example\">Schiff (sjif) — skip</div><div class=\"kurss-example\">Schraube (sjrábe) — skrúfa</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>sp og st í upphafi orðs</h4>\n              <p class=\"artikuli-explain\">Í upphafi orðs eða atkvæðis er „sp“ oft borið fram eins og „sjp“ og „st“ eins og „sjt“.</p>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">spielen (sjpílen) — leika / spila</div><div class=\"kurss-example\">Sprung (sjprúng) — stökk</div><div class=\"kurss-example\">stehen (sjtēen) — standa</div><div class=\"kurss-example\">Stall (sjtal) — fjós / gripahús</div><div class=\"kurss-example\">Stand (sjtant) — staða / bás</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>qu</h4>\n              <p class=\"artikuli-explain\">„qu“ er venjulega borið fram eins og „kv“ í þýsku.</p>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">Qual (kvāl) — kvöl</div><div class=\"kurss-example\">Quartier (kvartír) — gististaður / hverfi</div><div class=\"kurss-example\">quer (kvēr) — þvert / á ská</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>s og z</h4>\n              <p class=\"artikuli-explain\">Í upphafi orðs hljómar „s“ oft eins og raddað „z“ (eins og enska z; hljóðið er ekki til í íslensku). Bókstafurinn „z“ hljómar í þýsku eins og „ts“.</p>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">sagen (zāgen) — segja</div><div class=\"kurss-example\">singen (zingen) — syngja</div><div class=\"kurss-example\">Rose (rōze) — rós</div><div class=\"kurss-example\">Zahl (tsāl) — tala</div><div class=\"kurss-example\">Zeit (tsæt) — tími</div><div class=\"kurss-example\">Zink (tsink) — sink</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>v</h4>\n              <p class=\"artikuli-explain\">Í þýsku er „v“ oft borið fram eins og „f“. Í tökuorðum hljómar það oft eins og íslenskt „v“.</p>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">Vater (fāter) — faðir</div><div class=\"kurss-example\">von (fon) — frá / af</div><div class=\"kurss-example\">viel (fíl) — mikið / margt</div><div class=\"kurss-example\">vier (fír) — fjórir</div><div class=\"kurss-example\">Villa (vila) — villa</div><div class=\"kurss-example\">Klavier (klavír) — píanó</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>x og y</h4>\n              <p class=\"artikuli-explain\">„x“ er borið fram eins og „ks“ (eins og íslenskt x). „y“ er í sumum orðum borið fram eins og „ü“ (líkt og íslenskt „u“).</p>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">Felix (fēliks) — Felix</div><div class=\"kurss-example\">Axt (akst) — öxi</div><div class=\"kurss-example\">Mystik (mustik) — dulspeki</div><div class=\"kurss-example\">Mythe (mūte) — goðsögn</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>ß</h4>\n              <p class=\"artikuli-explain\">„ß“ er borið fram í þýsku eins og óraddað „s“.</p>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">Fuß (fús) — fótur</div><div class=\"kurss-example\">Füße (fūse) — fætur</div><div class=\"kurss-example\">Grüße (grūse) — kveðjur</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>✓</span>Samantekt</h4>\n              <ul class=\"kurss-summary-list\"><li>sch → sj</li><li>sp / st í upphafi → sjp / sjt</li><li>qu → kv</li><li>z → ts</li><li>v oft → f</li><li>x → ks</li><li>ß → s</li></ul>\n            </section>",
  "kurssVerbBasicsLesson": "\n            <h3>Undirstöðuatriði sagna</h3>\n            <div class=\"artikuli-info artikuli-intro-info\">\n              <span class=\"artikuli-info-icon\">i</span>\n              <div>Sagnir 1. kennslustundar og form þeirra (sagnbeyging)</div>\n            </div>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>Sagnir</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">kommen — að koma</div><div class=\"kurss-example\">gehen — að ganga</div><div class=\"kurss-example\">stehen — að standa</div><div class=\"kurss-example\">singen — að syngja</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>kommen</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">ich komme — ég kem</div><div class=\"kurss-example\">du kommst — þú kemur</div><div class=\"kurss-example\">er kommt — hann kemur</div><div class=\"kurss-example\">sie kommt — hún kemur</div><div class=\"kurss-example\">wir kommen — við komum</div><div class=\"kurss-example\">ihr kommt — þið komið</div><div class=\"kurss-example\">sie kommen — þeir / þær koma</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>gehen</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">ich gehe — ég geng</div><div class=\"kurss-example\">du gehst — þú gengur</div><div class=\"kurss-example\">er geht — hann gengur</div><div class=\"kurss-example\">sie geht — hún gengur</div><div class=\"kurss-example\">wir gehen — við göngum</div><div class=\"kurss-example\">ihr geht — þið gangið</div><div class=\"kurss-example\">sie gehen — þeir / þær ganga</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>stehen</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">ich stehe — ég stend</div><div class=\"kurss-example\">du stehst — þú stendur</div><div class=\"kurss-example\">er steht — hann stendur</div><div class=\"kurss-example\">sie steht — hún stendur</div><div class=\"kurss-example\">wir stehen — við stöndum</div><div class=\"kurss-example\">ihr steht — þið standið</div><div class=\"kurss-example\">sie stehen — þeir / þær standa</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>singen</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">ich singe — ég syng</div><div class=\"kurss-example\">du singst — þú syngur</div><div class=\"kurss-example\">er singt — hann syngur</div><div class=\"kurss-example\">sie singt — hún syngur</div><div class=\"kurss-example\">wir singen — við syngjum</div><div class=\"kurss-example\">ihr singt — þið syngið</div><div class=\"kurss-example\">sie singen — þeir / þær syngja</div></div>\n            </section>\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>Sagnir 2. kennslustundar</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">spielen — að spila</div><div class=\"kurss-example\">arbeiten — að vinna</div><div class=\"kurss-example\">fragen — að spyrja</div><div class=\"kurss-example\">antworten — að svara</div><div class=\"kurss-example\">rechnen — að reikna</div><div class=\"kurss-example\">zeichnen — að teikna</div><div class=\"kurss-example\">tun — að gera</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>spielen</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">ich spiele — ég spila</div><div class=\"kurss-example\">du spielst — þú spilar</div><div class=\"kurss-example\">er spielt — hann spilar</div><div class=\"kurss-example\">sie spielt — hún spilar</div><div class=\"kurss-example\">wir spielen — við spilum</div><div class=\"kurss-example\">ihr spielt — þið spilið</div><div class=\"kurss-example\">sie spielen — þeir / þær spila</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>arbeiten</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">ich arbeite — ég vinn</div><div class=\"kurss-example\">du arbeitest — þú vinnur</div><div class=\"kurss-example\">er arbeitet — hann vinnur</div><div class=\"kurss-example\">sie arbeitet — hún vinnur</div><div class=\"kurss-example\">wir arbeiten — við vinnum</div><div class=\"kurss-example\">ihr arbeitet — þið vinnið</div><div class=\"kurss-example\">sie arbeiten — þeir / þær vinna</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>fragen</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">ich frage — ég spyr</div><div class=\"kurss-example\">du fragst — þú spyrð</div><div class=\"kurss-example\">er fragt — hann spyr</div><div class=\"kurss-example\">sie fragt — hún spyr</div><div class=\"kurss-example\">wir fragen — við spyrjum</div><div class=\"kurss-example\">ihr fragt — þið spyrjið</div><div class=\"kurss-example\">sie fragen — þeir / þær spyrja</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>antworten</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">ich antworte — ég svara</div><div class=\"kurss-example\">du antwortest — þú svarar</div><div class=\"kurss-example\">er antwortet — hann svarar</div><div class=\"kurss-example\">sie antwortet — hún svarar</div><div class=\"kurss-example\">wir antworten — við svörum</div><div class=\"kurss-example\">ihr antwortet — þið svarið</div><div class=\"kurss-example\">sie antworten — þeir / þær svara</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>rechnen</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">ich rechne — ég reikna</div><div class=\"kurss-example\">du rechnest — þú reiknar</div><div class=\"kurss-example\">er rechnet — hann reiknar</div><div class=\"kurss-example\">sie rechnet — hún reiknar</div><div class=\"kurss-example\">wir rechnen — við reiknum</div><div class=\"kurss-example\">ihr rechnet — þið reiknið</div><div class=\"kurss-example\">sie rechnen — þeir / þær reikna</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>zeichnen</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">ich zeichne — ég teikna</div><div class=\"kurss-example\">du zeichnest — þú teiknar</div><div class=\"kurss-example\">er zeichnet — hann teiknar</div><div class=\"kurss-example\">sie zeichnet — hún teiknar</div><div class=\"kurss-example\">wir zeichnen — við teiknum</div><div class=\"kurss-example\">ihr zeichnet — þið teiknið</div><div class=\"kurss-example\">sie zeichnen — þeir / þær teikna</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>tun</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">ich tue — ég geri</div><div class=\"kurss-example\">du tust — þú gerir</div><div class=\"kurss-example\">er tut — hann gerir</div><div class=\"kurss-example\">sie tut — hún gerir</div><div class=\"kurss-example\">wir tun — við gerum</div><div class=\"kurss-example\">ihr tut — þið gerið</div><div class=\"kurss-example\">sie tun — þeir / þær gera</div></div>\n            </section>",
  "kurssSentenceStructureLesson": "\n            <h3>Setningaskipan</h3>\n            <div class=\"artikuli-info artikuli-intro-info\">\n              <span class=\"artikuli-info-icon\">i</span>\n              <div>Í spurnarsetningu stendur sögnin í þýsku venjulega í fyrsta sæti.</div>\n            </div>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>Dæmi</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">Du kommst. — Þú kemur.</div><div class=\"kurss-example\">Kommst du? — Kemur þú?</div><div class=\"kurss-example\">Er singt. — Hann syngur.</div><div class=\"kurss-example\">Singt er? — Syngur hann?</div><div class=\"kurss-example\">Stehst du? — Stendur þú?</div><div class=\"kurss-example\">Ja, ich stehe. — Já, ég stend.</div><div class=\"kurss-example\">Geht ihr? — Farið þið?</div><div class=\"kurss-example\">Ja, wir gehen. — Já, við förum.</div></div>\n            </section>\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>Spurningar með „was“</h4>\n              <p class=\"artikuli-explain\">Ef spurningin hefst á spurnarorði stendur sögnin í þýsku venjulega strax á eftir spurnarorðinu.</p>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">Was tust du? — Hvað gerir þú?</div><div class=\"kurss-example\">Was tut er? — Hvað gerir hann?</div><div class=\"kurss-example\">Was tut sie? — Hvað gerir hún?</div><div class=\"kurss-example\">Was tun sie? — Hvað gera þeir / þær?</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>Neitun með „nicht“</h4>\n              <p class=\"artikuli-explain\">Ef neitunin „nicht“ á við sögnina stendur hún í þýsku venjulega á eftir sögninni.</p>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">Ich spiele nicht. — Ég spila ekki.</div><div class=\"kurss-example\">Paul fragt nicht. — Paul spyr ekki.</div><div class=\"kurss-example\">Er kommt nicht. — Hann kemur ekki.</div><div class=\"kurss-example\">Sie singen nicht. — Þeir / þær syngja ekki.</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>Setningar úr 2. kennslustund</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">Spielst du? — Spilar þú?</div><div class=\"kurss-example\">Nein, ich spiele nicht, ich arbeite. — Nei, ég spila ekki, ég vinn.</div><div class=\"kurss-example\">Paul fragt nicht, er arbeitet. — Paul spyr ekki, hann vinnur.</div><div class=\"kurss-example\">Arbeitest du? — Vinnur þú?</div><div class=\"kurss-example\">Nein, ich arbeite nicht, ich singe. — Nei, ég vinn ekki, ég syng.</div><div class=\"kurss-example\">Was tut Paul? — Hvað gerir Paul?</div><div class=\"kurss-example\">Er spielt. — Hann spilar.</div><div class=\"kurss-example\">Was tut Marie? — Hvað gerir Marie?</div><div class=\"kurss-example\">Sie singt. — Hún syngur.</div><div class=\"kurss-example\">Paul spielt, aber Marie singt. — Paul spilar en Marie syngur.</div><div class=\"kurss-example\">Singt ihr? — Syngið þið?</div><div class=\"kurss-example\">Nein, wir singen nicht, wir arbeiten. — Nei, við syngjum ekki, við vinnum.</div><div class=\"kurss-example\">Was tun Paul und Marie? — Hvað gera Paul og Marie?</div><div class=\"kurss-example\">Sie fragen. — Þau spyrja.</div><div class=\"kurss-example\">Sie antworten nicht. — Þau svara ekki.</div><div class=\"kurss-example\">Wer arbeitet? — Hver vinnur?</div><div class=\"kurss-example\">Wir arbeiten. — Við vinnum.</div><div class=\"kurss-example\">Wir rechnen und zeichnen. — Við reiknum og teiknum.</div><div class=\"kurss-example\">Sie kommen, sie fragen, sie antworten, sie arbeiten, sie spielen, sie singen, sie gehen. — Þeir / þær koma, spyrja, svara, vinna, spila, syngja og fara.</div></div>\n            </section>",
  "kurssLesson1": "            <h3>Kennslustund 1</h3>\n            <p class=\"kurss-lesson-intro\">Fyrsta kennslustund: sagnir í nútíð, orð, framburður, málfræði og þýðing.</p>\n            <details class=\"lesson1-accordion\" open>\n              <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Sagnir í nútíð</span><span class=\"lesson1-chevron\">⌃</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-info\">Sagnir og beyging þeirra í nútíð.</div>\n                <div class=\"lesson1-verb-cards\">\n                  <article class=\"lesson1-verb-card\">\n                    <h4><span class=\"lesson1-verb-icon\">♟</span>kommen — koma</h4>\n                    <div class=\"lesson1-conjugation\"><span>ich</span><strong>komme</strong><span>ég kem</span><span>du</span><strong>kommst</strong><span>þú kemur</span><span>er / sie</span><strong>kommt</strong><span>hann / hún kemur</span><span>wir</span><strong>kommen</strong><span>við komum</span><span>ihr</span><strong>kommt</strong><span>þið komið</span><span>sie / Sie</span><strong>kommen</strong><span>þeir koma / þér komið</span></div>\n                  </article>\n                  <article class=\"lesson1-verb-card\">\n                    <h4><span class=\"lesson1-verb-icon\">♟</span>gehen — fara</h4>\n                    <div class=\"lesson1-conjugation\"><span>ich</span><strong>gehe</strong><span>ég fer</span><span>du</span><strong>gehst</strong><span>þú ferð</span><span>er / sie</span><strong>geht</strong><span>hann / hún fer</span><span>wir</span><strong>gehen</strong><span>við förum</span><span>ihr</span><strong>geht</strong><span>þið farið</span><span>sie / Sie</span><strong>gehen</strong><span>þeir fara / þér farið</span></div>\n                  </article>\n                  <article class=\"lesson1-verb-card\">\n                    <h4><span class=\"lesson1-verb-icon\">♟</span>stehen — standa</h4>\n                    <div class=\"lesson1-conjugation\"><span>ich</span><strong>stehe</strong><span>ég stend</span><span>du</span><strong>stehst</strong><span>þú stendur</span><span>er / sie</span><strong>steht</strong><span>hann / hún stendur</span><span>wir</span><strong>stehen</strong><span>við stöndum</span><span>ihr</span><strong>steht</strong><span>þið standið</span><span>sie / Sie</span><strong>stehen</strong><span>þeir standa / þér standið</span></div>\n                  </article>\n                  <article class=\"lesson1-verb-card\">\n                    <h4><span class=\"lesson1-verb-icon\">♟</span>singen — syngja</h4>\n                    <div class=\"lesson1-conjugation\"><span>ich</span><strong>singe</strong><span>ég syng</span><span>du</span><strong>singst</strong><span>þú syngur</span><span>er / sie</span><strong>singt</strong><span>hann / hún syngur</span><span>wir</span><strong>singen</strong><span>við syngjum</span><span>ihr</span><strong>singt</strong><span>þið syngið</span><span>sie / Sie</span><strong>singen</strong><span>þeir syngja / þér syngið</span></div>\n                  </article>\n                </div>\n                <section class=\"lesson1-block\">\n                  <h4>Dæmi</h4>\n                  <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Stehst du?<br>Ja, ich stehe.</div><div class=\"kurss-example\">Steht Albert?<br>Ja, er steht.</div><div class=\"kurss-example\">Steht Marta?<br>Ja, sie steht.</div><div class=\"kurss-example\">Wer kommt und singt?<br>Albert und Marta kommen und singen.</div><div class=\"kurss-example\">Geht ihr?<br>Ja, wir gehen.</div><div class=\"kurss-example\">Wer steht und singt?<br>Albert und Marta stehen und singen.</div></div>\n                </section>\n              </div>\n            </details>\n            <details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Orð</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-info lesson1-vardini-info\"><span class=\"lesson1-info-icon\" aria-hidden=\"true\">i</span><span>Áætlaður framburður orðanna er gefinn í svigum með íslenskum stöfum.<br>Hafðu þetta einnig í huga í næstu kennslustundum.</span></div>\n                <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">wir (vír) — við</div><div class=\"kurss-example\">Í orðinu „wir“ er bókstafurinn i borinn fram langur.</div><div class=\"kurss-example\">kommen (kommen) — koma</div><div class=\"kurss-example\">gehen (ge-en) — fara</div><div class=\"kurss-example\">stehen (sjte-en) — standa</div><div class=\"kurss-example\">singen (singen) — syngja</div><div class=\"kurss-example\">du (dú) kommst — þú kemur</div><div class=\"kurss-example\">er (er) kommt — hann kemur</div><div class=\"kurss-example\">sie (sí) kommt — hún kemur</div><div class=\"kurss-example\">wer (ver) — hver?</div><div class=\"kurss-example\">ja (ja) — já</div></div>\n              </div>\n            </details>\n                        <details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Framburður</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Réttur framburður orðanna, ritaður með íslenskum stöfum, er gefinn í kennslustundunum.</div><div class=\"kurss-example\">Wir (vír) — við. Í wir er í alltaf borið fram langt.</div></div>\n              </div>\n            </details>\n<details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Málfræði</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content lesson1-grammar-content\">\n                <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>∞</span>Nafnháttur</h4><div class=\"lesson1-grammar-note\">Grunnmynd sagnarinnar. Venjulega endar nafnhátturinn á -en.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">kommen</div><div class=\"kurss-example\">gehen</div><div class=\"kurss-example\">stehen</div><div class=\"kurss-example\">singen</div></div></section>\n                <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>♟</span>Nútíðarendingar</h4><div class=\"lesson1-ending-info\"><span class=\"lesson1-info-icon\" aria-hidden=\"true\">i</span><div class=\"lesson1-ending-info-body\"><p><strong>Taktu <span class=\"lesson1-ending-accent\">-en</span> af grunnmynd sagnarinnar og bættu endingunni við.</strong></p><p>Dæmi: kommen → komm + ending</p><div class=\"lesson1-ending-process\" aria-label=\"Hvernig nútíðarendingar eru myndaðar\"><div class=\"lesson1-ending-step\"><strong>kommen</strong><span>grunnmynd</span></div><span class=\"lesson1-ending-arrow\">→</span><div class=\"lesson1-ending-step\"><strong>taktu af <span class=\"lesson1-ending-accent\">-en</span></strong><span>stofninn verður eftir</span></div><span class=\"lesson1-ending-arrow\">→</span><div class=\"lesson1-ending-step\"><strong>komm</strong><span>stofn</span></div><span class=\"lesson1-ending-arrow\">→</span><div class=\"lesson1-ending-step\"><strong>bættu endingunni við</strong><span>e / st / t</span></div><span class=\"lesson1-ending-arrow\">→</span><div class=\"lesson1-ending-results\"><div>komm + <span class=\"lesson1-ending-accent\">e</span> = <strong>komme</strong></div><div>komm + <span class=\"lesson1-ending-accent\">st</span> = <strong>kommst</strong></div><div>komm + <span class=\"lesson1-ending-accent\">t</span> = <strong>kommt</strong></div></div></div></div></div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich → -e</div><div class=\"kurss-example\">du → -st</div><div class=\"kurss-example\">er / sie → -t</div><div class=\"kurss-example\">wir → -en</div><div class=\"kurss-example\">ihr → -t</div><div class=\"kurss-example\">sie → -en</div></div></section>\n                <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>●</span>Dæmi</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich komme</div><div class=\"kurss-example\">du kommst</div><div class=\"kurss-example\">er kommt</div><div class=\"kurss-example\">wir kommen</div></div></section>\n                <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>?</span>Spurnarsetningar</h4><div class=\"lesson1-grammar-info\"><span class=\"lesson1-info-icon\" aria-hidden=\"true\">i</span><span>Í þýskri spurnarsetningu færist sögnin venjulega í fyrsta sæti.</span></div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Á íslensku:<br>Þú kemur.<br>Kemur þú?</div><div class=\"kurss-example\">Á þýsku:<br>Du kommst.<br>Kommst du?</div><div class=\"kurss-example\">du kommst — þú kemur<br>kommst du? — kemur þú?</div><div class=\"kurss-example\">er singt — hann syngur<br>singt er? — syngur hann?</div></div></section>\n                <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>♣</span>Munur á persónum</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">er kommt — hann kemur</div><div class=\"kurss-example\">sie kommt — hún kemur</div><div class=\"kurss-example\">sie kommen — þeir / þær koma</div></div></section>\n              </div>\n            </details>\n                        <details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Þýddu</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-training-wrap\">\n                  <button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson1-training-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"Kennslustund 1: æfingaspjald\">\n                    <span class=\"lesson1-training-progress\">Kennslustund 1 · Þýddu: 1 / 11</span>\n                    <span class=\"lesson1-training-text\">Kemur þú?</span>\n                  </button>\n                  <p class=\"lesson1-training-hint\">Smelltu á spjaldið til að sjá þýsku þýðinguna. Eftir svarið sýnir næsti smellur næsta spjald.</p>\n                </div>\n              </div>\n            </details>",
  "kurssLesson2": "            <h3>Kennslustund 2</h3>\n            <p class=\"kurss-lesson-intro\">Önnur kennslustund: samtöl, orð, framburður, málfræði og þýðing.</p>\n            <details class=\"lesson1-accordion\" open>\n              <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Samtöl / setningar</span><span class=\"lesson1-chevron\">⌃</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-card-grid\">\n                  <div class=\"kurss-example\">Spielst du?<br>Nein, ich spiele nicht, ich arbeite.</div>\n                  <div class=\"kurss-example\">Paul fragt nicht, er arbeitet.</div>\n                  <div class=\"kurss-example\">Arbeitest du?<br>Nein, ich arbeite nicht, ich singe.</div>\n                  <div class=\"kurss-example\">Was tut Paul?<br>Er spielt.</div>\n                  <div class=\"kurss-example\">Was tut Marie?<br>Sie singt.</div>\n                  <div class=\"kurss-example\">Paul spielt, aber Marie singt.</div>\n                  <div class=\"kurss-example\">Singt ihr?<br>Nein, wir singen nicht, wir arbeiten.</div>\n                  <div class=\"kurss-example\">Was tun Paul und Marie?<br>Sie fragen.<br>Sie antworten nicht.</div>\n                  <div class=\"kurss-example\">Wer arbeitet?<br>Wir arbeiten.<br>Wir rechnen und zeichnen.</div>\n                  <div class=\"kurss-example\">Sie kommen, sie fragen, sie antworten, sie arbeiten, sie spielen, sie singen, sie gehen.</div>\n                </div>\n              </div>\n            </details>\n            <details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Orð</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-card-grid\">\n                  <div class=\"kurss-example\">spielen — leika sér; spila</div>\n                  <div class=\"kurss-example\">nein — nei</div>\n                  <div class=\"kurss-example\">nicht — ekki</div>\n                  <div class=\"kurss-example\">arbeiten — vinna</div>\n                  <div class=\"kurss-example\">fragen — spyrja</div>\n                  <div class=\"kurss-example\">was tut er? — hvað gerir hann?</div>\n                  <div class=\"kurss-example\">was tun sie? — hvað gera þeir / þær?</div>\n                  <div class=\"kurss-example\">aber — en</div>\n                  <div class=\"kurss-example\">antworten — svara</div>\n                  <div class=\"kurss-example\">rechnen — reikna</div>\n                  <div class=\"kurss-example\">zeichnen — teikna</div>\n                  <div class=\"kurss-example\">Marie — María</div>\n                </div>\n              </div>\n            </details>\n                        <details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Framburður</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Í orðunum ich, nicht, rechnen, zeichnen er hljóðið ch borið fram mjúkt, um það bil eins og hj í íslensku orðunum: hjá, hjól.</div><div class=\"kurss-example\">Í orðunum arbeiten, zeichnen er tvíhljóðið ei borið fram um það bil eins og íslenskt æ.</div><div class=\"kurss-example\">Samhljóðaklasinn sp er borinn fram sem sjp: spielen (sjpílen).</div><div class=\"kurss-example\">Í sögninni tun er u borið fram langt í öllum persónum.</div></div>\n              </div>\n            </details>\n<details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Málfræði</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content lesson1-grammar-content\">\n                <section class=\"lesson1-block\">\n                  <h4 class=\"lesson1-grammar-header\"><span>1</span>Endingar með e</h4>\n                  <div class=\"lesson1-grammar-note\">Ef stofn sagnar endar á t, d, chn, kemur e á undan endingunum -st og -t í beygingu.</div>\n                  <h5 class=\"lesson2-subtitle\">arbeiten</h5>\n                  <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich arbeite</div><div class=\"kurss-example\">du arbeitest</div><div class=\"kurss-example\">er arbeitet</div><div class=\"kurss-example\">sie arbeitet</div><div class=\"kurss-example\">wir arbeiten</div><div class=\"kurss-example\">ihr arbeitet</div><div class=\"kurss-example\">sie arbeiten</div></div>\n                  <h5 class=\"lesson2-subtitle\">rechnen</h5>\n                  <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich rechne</div><div class=\"kurss-example\">du rechnest</div><div class=\"kurss-example\">er rechnet</div><div class=\"kurss-example\">sie rechnet</div><div class=\"kurss-example\">wir rechnen</div><div class=\"kurss-example\">ihr rechnet</div><div class=\"kurss-example\">sie rechnen</div></div>\n                  <h5 class=\"lesson2-subtitle\">tun</h5>\n                  <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich tue</div><div class=\"kurss-example\">du tust</div><div class=\"kurss-example\">er tut</div><div class=\"kurss-example\">sie tut</div><div class=\"kurss-example\">wir tun</div><div class=\"kurss-example\">ihr tut</div><div class=\"kurss-example\">sie tun</div></div>\n                </section>\n                <section class=\"lesson1-block\">\n                  <h4 class=\"lesson1-grammar-header\"><span>2</span>Spurnarorð</h4>\n                  <div class=\"lesson1-grammar-note\">Í spurnarsetningum sem hefjast á spurnarorði, til dæmis: hvað? hver? hvaða? hvers vegna? af hverju? o.s.frv., stendur sögnin strax á eftir spurnarorðinu.</div>\n                  <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Was tust du? — Hvað gerir þú?</div><div class=\"kurss-example\">Was tut er? — Hvað gerir hann?</div><div class=\"kurss-example\">Was tut sie? — Hvað gerir hún?</div><div class=\"kurss-example\">Was tun sie? — Hvað gera þeir / þær?</div></div>\n                </section>\n                <section class=\"lesson1-block\">\n                  <h4 class=\"lesson1-grammar-header\"><span>3</span>Neitun með nicht</h4>\n                  <div class=\"lesson1-grammar-note\">Ef neitunin nicht á við sögnina, stendur neitunarorðið á eftir sögninni.</div>\n                  <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Er kommt nicht. — Hann kemur ekki.</div><div class=\"kurss-example\">Sie singen nicht. — Þeir syngja ekki.</div></div>\n                </section>\n              </div>\n            </details>\n                                    <details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Þýddu</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-training-wrap\">\n                  <button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson2-training-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"Kennslustund 2: þýðingarspjald\">\n                    <span class=\"lesson1-training-progress\">Kennslustund 2 · Þýddu: 1 / 15</span>\n                    <span class=\"lesson1-training-text\">Hver spyr?</span>\n                  </button>\n                  <p class=\"lesson1-training-hint\">Smelltu á spjaldið til að sjá þýsku þýðinguna. Eftir svarið sýnir næsti smellur næsta spjald.</p>\n                </div>\n              </div>\n            </details>",
  "kurssLesson3": "            <h3>Kennslustund 3</h3>\n            <p class=\"kurss-lesson-intro\">Þriðja kennslustund: samtöl, orð, framburður, málfræði og þýðing.</p>\n            <details class=\"lesson1-accordion\" open>\n              <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Samtöl / setningar</span><span class=\"lesson1-chevron\">⌃</span></summary>\n              <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Wer rechnet und zeichnet?<br>Wir rechnen und zeichnen.</div><div class=\"kurss-example\">Wer kommt?<br>Paul und Anna kommen.</div><div class=\"kurss-example\">Was steht hier?<br>Hier steht ein Tisch.</div><div class=\"kurss-example\">Was steht dort?<br>Dort steht eine Bank.</div><div class=\"kurss-example\">Was liegt hier?<br>Hier liegt ein Buch.</div><div class=\"kurss-example\">Was liegt dort?<br>Dort liegt ein Heft.</div><div class=\"kurss-example\">Was hängt hier?<br>Hier hängt ein Bild.</div><div class=\"kurss-example\">Was hängt dort?<br>Dort hängt eine Tafel.</div><div class=\"kurss-example\">Wie ist das Buch?<br>Das Buch ist dick.</div><div class=\"kurss-example\">Wie ist das Heft?<br>Das Heft ist dünn.</div><div class=\"kurss-example\">Wie ist die Bank?<br>Die Bank ist niedrig.</div><div class=\"kurss-example\">Wie ist der Tisch?<br>Der Tisch ist hoch.</div></div></div>\n            </details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Orð</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">wer — hver</div><div class=\"kurss-example\">was — hvað</div><div class=\"kurss-example\">hier — hér</div><div class=\"kurss-example\">dort — þar</div><div class=\"kurss-example\">der Tisch — borðið</div><div class=\"kurss-example\">ein Tisch — borð</div><div class=\"kurss-example\">die Bank — bekkurinn</div><div class=\"kurss-example\">eine Bank — bekkur</div><div class=\"kurss-example\">liegen — liggja</div><div class=\"kurss-example\">liegt hier ein Buch? — er / liggur bók hér?</div><div class=\"kurss-example\">das Buch — bókin</div><div class=\"kurss-example\">ein Buch — bók</div><div class=\"kurss-example\">hängen — hanga</div><div class=\"kurss-example\">das Bild — myndin</div><div class=\"kurss-example\">ein Bild — mynd</div><div class=\"kurss-example\">die Tafel — taflan</div><div class=\"kurss-example\">eine Tafel — tafla</div><div class=\"kurss-example\">wie — hvernig</div><div class=\"kurss-example\">ist — er</div><div class=\"kurss-example\">dick — þykkur, feitur</div><div class=\"kurss-example\">das Heft — stílabókin</div><div class=\"kurss-example\">ein Heft — stílabók</div><div class=\"kurss-example\">dünn — þunnur, grannur</div><div class=\"kurss-example\">niedrig — lágur</div><div class=\"kurss-example\">hoch — hár</div></div></div></details>\n                        <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Framburður</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Langt í-hljóð er í þýsku táknað með ie: liegen (lígen), hier (hír), wie (ví).</div><div class=\"kurss-example\">ck er tvöfalt k: dick (dikk).</div><div class=\"kurss-example\">Í lýsingarorðum og atviksorðum hljómar endingin -ig eins og mjúkt -ich: niedrig (nídrihj).</div><div class=\"kurss-example\">Ef e fylgir endingunni -ig, þ.e. -ige, er g borið fram sem hart g: niedrige (nídrige) Bänke.</div></div></div></details>\n<details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Málfræði</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content lesson1-grammar-content\"><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>1</span>Frumlag</h4><div class=\"lesson1-grammar-note\">Frumlagið í þýsku svarar spurningunni wer? / was? og stendur í nefnifalli.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Með wer? er spurt um persónur.</div><div class=\"kurss-example\">Með was? er spurt um hluti.</div><div class=\"kurss-example\">Wer singt? — Sie singt.</div><div class=\"kurss-example\">Was liegt hier? — Hier liegt ein Buch.</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>2</span>Greinar</h4><div class=\"lesson1-grammar-note\">Í þýsku hafa nafnorð 3 kyn: karlkyn, kvenkyn og hvorugkyn. Á undan nafnorðum stendur venjulega lítið orð sem kallast greinir. Þetta orð er ekki þýtt sérstaklega.</div><h5 class=\"lesson2-subtitle\">Ákveðinn greinir</h5><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">karlkyn — der</div><div class=\"kurss-example\">kvenkyn — die</div><div class=\"kurss-example\">hvorugkyn — das</div><div class=\"kurss-example\">Í fleirtölu er ákveðni greinirinn die í öllum þremur kynjum.</div><div class=\"kurss-example\">der Tisch — die Tische</div><div class=\"kurss-example\">die Bank — die Bänke</div><div class=\"kurss-example\">das Heft — die Hefte</div></div><h5 class=\"lesson2-subtitle\">Óákveðinn greinir</h5><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">karlkyn — ein</div><div class=\"kurss-example\">kvenkyn — eine</div><div class=\"kurss-example\">hvorugkyn — ein</div><div class=\"kurss-example\">Óákveðni greinirinn hefur enga fleirtölu.</div><div class=\"kurss-example\">ein Tisch — Tische</div><div class=\"kurss-example\">ein Heft — Hefte</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>3</span>Sérnöfn</h4><div class=\"lesson1-grammar-note\">Á undan sérnöfnum er greinir ekki notaður.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Hans spielt, aber Marie singt.</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>4</span>Staða sagnarinnar</h4><div class=\"lesson1-grammar-note\">Í fullyrðingarsetningu stendur sögnin í öðru sæti.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Hier hängt eine Karte.</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>5</span>stehen / liegen / hängen</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Á þýsku er sagt um hluti sem eru uppréttir að þeir standi:<br>der Tisch steht<br>die Bank steht</div><div class=\"kurss-example\">Um hluti sem eru í láréttri stöðu er sagt að þeir liggi:<br>das Buch liegt<br>das Heft liegt</div><div class=\"kurss-example\">Hlutir geta líka hangið:<br>die Karte hängt<br>die Tafel hängt</div></div></section></div></details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Þýddu</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-training-wrap\"><button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson3-training-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"Kennslustund 3: þýðingarspjald\"><span class=\"lesson1-training-progress\">Kennslustund 3 · Þýddu: 1 / 22</span><span class=\"lesson1-training-text\">Reiknar þú?</span></button><p class=\"lesson1-training-hint\">Smelltu á spjaldið til að sjá þýsku þýðinguna. Eftir svarið sýnir næsti smellur næsta spjald.</p></div></div></details>",
  "kurssLesson4": "            <h3>Kennslustund 4</h3>\n            <p class=\"kurss-lesson-intro\">Þolfall, nehmen, hinlegen, hinausgehen og lýsingarorð.</p>\n            <details class=\"lesson1-accordion\" open>\n              <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Samtöl / setningar</span><span class=\"lesson1-chevron\">⌃</span></summary>\n              <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Paul kommt und nimmt einen Federhalter.</div><div class=\"kurss-example\">Er zeigt den Federhalter.</div><div class=\"kurss-example\">Er fragt: „Wie ist der Federhalter?“</div><div class=\"kurss-example\">Olga antwortet: „Der Federhalter ist schwarz.“</div><div class=\"kurss-example\">Ist der Federhalter weiß? Nein, der Federhalter ist nicht weiß, er ist schwarz.</div><div class=\"kurss-example\">Marie kommt und nimmt eine Feder.</div><div class=\"kurss-example\">Sie fragt: „Wie ist die Feder?“</div><div class=\"kurss-example\">Olga antwortet: „Die Feder ist spitz.“</div><div class=\"kurss-example\">Ist die Feder stumpf? Nein, die Feder ist nicht stumpf, sie ist spitz.</div><div class=\"kurss-example\">Was legt das Mädchen hin? Es legt die Feder hin.</div><div class=\"kurss-example\">Was nimmst du? Ich nehme ein Messer.</div><div class=\"kurss-example\">Wie ist das Messer? Das Messer ist scharf.</div><div class=\"kurss-example\">Ist das Messer stumpf? Nein, es ist nicht stumpf, es ist scharf.</div><div class=\"kurss-example\">Was legst du hin? Ich lege das Messer, die Feder und den Federhalter hin.</div><div class=\"kurss-example\">Dann gehe ich hinaus und arbeite.</div></div></div>\n            </details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Orð</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">nehmen (nemen) — taka</div><div class=\"kurss-example\">er nimmt (nimt) — hann tekur</div><div class=\"kurss-example\">der Federhalter (der federhalter) — pennaskaftið</div><div class=\"kurss-example\">einen Federhalter — pennaskaft</div><div class=\"kurss-example\">zeigen — sýna</div><div class=\"kurss-example\">schwarz (sjvarts) — svartur</div><div class=\"kurss-example\">weiß (væs) — hvítur</div><div class=\"kurss-example\">die Feder (dí feder) — penninn</div><div class=\"kurss-example\">eine Feder — penna</div><div class=\"kurss-example\">spitz (sjpits) — oddhvass</div><div class=\"kurss-example\">hinlegen — leggja frá sér</div><div class=\"kurss-example\">legt hin — leggur frá sér</div><div class=\"kurss-example\">das Mädchen (medhjen) — stúlkan</div><div class=\"kurss-example\">das Messer — hnífurinn</div><div class=\"kurss-example\">ein Messer — hníf</div><div class=\"kurss-example\">scharf — beittur</div><div class=\"kurss-example\">stumpf (sjtumpf) — bitlaus, sljór</div><div class=\"kurss-example\">dann — þá, síðan</div><div class=\"kurss-example\">hinaus — út</div><div class=\"kurss-example\">hinausgehen — fara út, ganga út</div></div></div></details>\n                        <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Framburður</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Endingarnar -en, -er, -el eru áherslulausar og því heyrist e í þessum endingum illa: kommen, nehmen, der Federhalter.</div><div class=\"kurss-example\">Í þýsku getur h bæði verið hljóð og lengdarmerki fyrir sérhljóðið á undan.</div><div class=\"kurss-example\">Ef h er lengdarmerki er það ekki borið fram sem hljóð: nehmen (nemen).</div><div class=\"kurss-example\">Ef aðeins eitt samhljóð fylgir sérhljóði er sérhljóðið borið fram langt: die (dí) Feder (feder), den (den).</div></div></div></details>\n<details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Málfræði</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content lesson1-grammar-content\"><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>1</span>Þolfall</h4><div class=\"lesson1-grammar-note\">Í kvenkyni og hvorugkyni er þolfall eins og nefnifall. Aðeins karlkynið breytist.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Nominativ: der Federhalter, die Feder, das Messer.</div><div class=\"kurss-example\">Akkusativ: den Federhalter, die Feder, das Messer.</div><div class=\"kurss-example\">Nominativ: ein Federhalter, eine Feder, ein Messer.</div><div class=\"kurss-example\">Akkusativ: einen Federhalter, eine Feder, ein Messer.</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>2</span>nehmen</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich nehme</div><div class=\"kurss-example\">du nimmst</div><div class=\"kurss-example\">er/sie nimmt</div><div class=\"kurss-example\">wir nehmen</div><div class=\"kurss-example\">ihr nehmt</div><div class=\"kurss-example\">sie nehmen</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>3</span>Fornöfn</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">er — karlkyn</div><div class=\"kurss-example\">sie — kvenkyn</div><div class=\"kurss-example\">es — hvorugkyn</div><div class=\"kurss-example\">í fleirtölu — sie</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>4</span>Aðskiljanlegar sagnir</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">hinlegen → ich lege das Messer hin</div><div class=\"kurss-example\">hinausgehen → Marie geht hinaus</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>5</span>Lýsingarorð</h4><div class=\"lesson1-grammar-note\">Ef lýsingarorð er sagnfylling í setningu breytist það hvorki eftir kyni né tölu.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">der Federhalter ist klein</div><div class=\"kurss-example\">die Feder ist klein</div><div class=\"kurss-example\">das Messer ist klein</div><div class=\"kurss-example\">die Messer sind klein</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>6</span>Neitun með nicht</h4><div class=\"lesson1-grammar-note\">Ef nicht neitar lýsingarorði stendur það á undan orðinu sem neitað er.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">der Federhalter ist nicht weiß</div><div class=\"kurss-example\">das Messer ist nicht scharf</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>7</span>-chen / -lein</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Nafnorð með endingunni -chen og -lein eru hvorugkyns: das Mädchen.</div></div></section></div></details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Þýddu</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-training-wrap\"><button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson4-training-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"Kennslustund 4: þýðingarspjald\"><span class=\"lesson1-training-progress\">Kennslustund 4 · Þýddu: 1 / 16</span><span class=\"lesson1-training-text\">Stúlkan tekur pennaskaft.</span></button><p class=\"lesson1-training-hint\">Smelltu á spjaldið til að sjá þýsku þýðinguna. Eftir svarið sýnir næsti smellur næsta spjald.</p></div></div></details>",
  "kurssLesson5": "\n    <h3>Kennslustund 5</h3>\n    <p class=\"kurss-lesson-intro\">Wen?, þolfall, sitzen, fragen og endingin -in.</p>\n\n    <details class=\"lesson1-accordion\" open>\n      <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Samtöl / setningar</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\">\n        <div class=\"kurss-example\">Wer sitzt und fragt? Der Lehrer sitzt und fragt.</div>\n        <div class=\"kurss-example\">Wer steht und antwortet? Der Schüler steht und antwortet.</div>\n        <div class=\"kurss-example\">Wie antwortet der Schüler? Der Schüler antwortet gut.</div>\n        <div class=\"kurss-example\">Wen lobt der Lehrer? Der Lehrer lobt den Schüler.</div>\n        <div class=\"kurss-example\">Wie ist der Schüler? Der Schüler ist klein.</div>\n        <div class=\"kurss-example\">Ist der Schüler klein oder groß? Er ist klein.</div>\n        <div class=\"kurss-example\">Wen fragt die Lehrerin? Die Lehrerin fragt die Schülerin.</div>\n        <div class=\"kurss-example\">Wie antwortet die Schülerin? Die Schülerin antwortet schlecht.</div>\n        <div class=\"kurss-example\">Was tut die Lehrerin? Sie tadelt die Schülerin.</div>\n        <div class=\"kurss-example\">Die Schülerin ist nicht klein, sie ist groß.</div>\n        <div class=\"kurss-example\">Ein Kind spielt. Das Kind ist artig.</div>\n        <div class=\"kurss-example\">Die Mutter liebt das Kind. Der Vater lobt das Kind.</div>\n      </div></div>\n    </details>\n\n    <details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Orð</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\">\n        <div class=\"kurss-example\">sitzen (sitsen) — sitja</div>\n        <div class=\"kurss-example\">fragen (fragen) — spyrja</div>\n        <div class=\"kurss-example\">der Lehrer (der lerer) — kennarinn</div>\n        <div class=\"kurss-example\">gut (gút) — vel</div>\n        <div class=\"kurss-example\">wen (ven) — hvern</div>\n        <div class=\"kurss-example\">loben — hrósa</div>\n        <div class=\"kurss-example\">der Schüler (sjuler) — nemandinn</div>\n        <div class=\"kurss-example\">klein — lítill</div>\n        <div class=\"kurss-example\">groß (gros) — stór</div>\n        <div class=\"kurss-example\">die Lehrerin — kennslukonan</div>\n        <div class=\"kurss-example\">die Schülerin — skólastúlkan</div>\n        <div class=\"kurss-example\">schlecht (sjlehjt) — illa</div>\n        <div class=\"kurss-example\">tadeln — ávíta</div>\n        <div class=\"kurss-example\">oder (oder) — eða</div>\n        <div class=\"kurss-example\">das Kind (kint) — barnið</div>\n        <div class=\"kurss-example\">artig (artihj) — þægur</div>\n        <div class=\"kurss-example\">die Mutter — móðirin</div>\n        <div class=\"kurss-example\">lieben (líben) — elska</div>\n        <div class=\"kurss-example\">der Vater (fater) — faðirinn</div>\n      </div></div>\n    </details>\n\n        <details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Framburður</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\">\n        <div class=\"kurss-example\">tz er tvöfaldað z og er borið fram eins og þýskt z, þ.e. ts: sitzen (sitsen).</div>\n        <div class=\"kurss-example\">v í þýskum orðum er borið fram eins og f: der Vater (fater).</div>\n        <div class=\"kurss-example\">ß kallast Eszett og er borið fram eins og íslenskt s: groß (gros), weiß (væs).</div>\n      </div></div>\n    </details>\n\n<details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Málfræði</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content lesson1-grammar-content\">\n        <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">Nefnifall og þolfall</h4><div class=\"lesson1-grammar-note\">Í íslensku svarar nefnifall spurningunni hver?, en þolfall spurningunni hvern?.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Í þýsku er spurt í nefnifalli með wer? um persónur og með was? um hluti.</div><div class=\"kurss-example\">Í þolfalli er spurt með wen? um persónur og með was? um hluti.</div></div></section>\n        <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">Breyting greinisins í þolfalli</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Nominativ: der Vater, die Mutter, das Kind.</div><div class=\"kurss-example\">Akkusativ: den Vater, die Mutter, das Kind.</div><div class=\"kurss-example\">Nominativ: der Federhalter, die Feder, das Messer.</div><div class=\"kurss-example\">Akkusativ: den Federhalter, die Feder, das Messer.</div></div></section>\n        <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">sitzen</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich sitze</div><div class=\"kurss-example\">du sitzt</div><div class=\"kurss-example\">er/sie/es sitzt</div><div class=\"kurss-example\">wir sitzen</div><div class=\"kurss-example\">ihr sitzt</div><div class=\"kurss-example\">sie sitzen</div></div></section>\n        <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">fragen + þolfall</h4><div class=\"lesson1-grammar-note\">Sögnin fragen stýrir þolfalli í þýsku.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Wen fragt der Lehrer?</div><div class=\"kurss-example\">Der Lehrer fragt den Schüler.</div></div></section>\n        <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">Endingin -in</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Mörg kvenkynsorð eru mynduð með endingunni -in.</div><div class=\"kurss-example\">die Lehrerin</div><div class=\"kurss-example\">die Schülerin</div></div></section>\n        <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">Staða sagnarinnar</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Í fullyrðingarsetningu stendur sögnin í öðru sæti.</div><div class=\"kurss-example\">Dann geht das Mädchen hinaus und arbeitet.</div><div class=\"kurss-example\">Das Mädchen geht dann hinaus und arbeitet.</div></div></section>\n      </div>\n    </details>\n\n    <details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Þýddu</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-training-wrap\"><button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson5-training-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"Kennslustund 5: þýðingarspjald\"><span class=\"lesson1-training-progress\">Kennslustund 5 · Þýddu: 1 / 16</span><span class=\"lesson1-training-text\">Hvern elskar faðirinn?</span></button><p class=\"lesson1-training-hint\">Smelltu á spjaldið til að sjá þýsku þýðinguna. Eftir svarið sýnir næsti smellur næsta spjald.</p></div></div>\n    </details>\n  ",
  "kurssLesson6": "\n    <h3>Kennslustund 6</h3>\n    <p class=\"kurss-lesson-intro\">Tölur, fleirtala, hljóðvarp og fleirtölumyndir nafnorða.</p>\n\n    <details class=\"lesson1-accordion\" open>\n      <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Samtöl / setningar</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Hier liegt ein Bleistift.</div><div class=\"kurss-example\">Dort liegen einige Messer.</div><div class=\"kurss-example\">Edgar nimmt ein Messer, zwei Messer, drei Messer.</div><div class=\"kurss-example\">Er legt die Messer wieder hin.</div><div class=\"kurss-example\">Alle Messer sind scharf.</div><div class=\"kurss-example\">Dann nimmt er wieder ein Messer.</div><div class=\"kurss-example\">Er macht das Messer auf.</div><div class=\"kurss-example\">Er nimmt den Bleistift.</div><div class=\"kurss-example\">Er spitzt den Bleistift an.</div><div class=\"kurss-example\">Er legt das Messer hin.</div><div class=\"kurss-example\">Er setzt sich und zeichnet.</div><div class=\"kurss-example\">Was zeichnet er? Er zeichnet einen Schlüssel.</div><div class=\"kurss-example\">Gertrud zeichnet ein Fenster und eine Tafel.</div><div class=\"kurss-example\">Anna zeichnet einen Garten.</div><div class=\"kurss-example\">Hier liegen vier Löffel.</div><div class=\"kurss-example\">Dort liegen fünf Nadeln.</div><div class=\"kurss-example\">Gertrud kommt und zählt die Löffel: das ist ein Löffel; das sind zwei, drei, vier Löffel.</div><div class=\"kurss-example\">Anna zählt die Nadeln: das ist eine Nadel; das sind zwei, drei, vier, fünf Nadeln.</div><div class=\"kurss-example\">Wieviel Nadeln sind hier?</div><div class=\"kurss-example\">Hier ist eine Nadel.</div><div class=\"kurss-example\">Dort sind zwei, drei, vier Nadeln.</div><div class=\"kurss-example\">Fünf Schlüssel sind hier.</div><div class=\"kurss-example\">Sechs Löffel sind dort.</div><div class=\"kurss-example\">Was ist das?</div><div class=\"kurss-example\">Das ist ein Hammer. Das sind fünf Hämmer.</div><div class=\"kurss-example\">Das ist ein Deckel. Das sind sechs Deckel.</div><div class=\"kurss-example\">Das ist ein Eimer. Das sind sieben Eimer.</div><div class=\"kurss-example\">Das ist ein Teller. Das sind acht Teller.</div><div class=\"kurss-example\">Das ist ein Wagen. Das sind neun Wagen.</div><div class=\"kurss-example\">Das ist ein Schlitten. Das sind zehn Schlitten.</div><div class=\"kurss-example\">Wie sind die Dinge?</div><div class=\"kurss-example\">Der Hammer ist klein. Die Hämmer sind klein.</div><div class=\"kurss-example\">Der Deckel ist groß. Die Deckel sind groß.</div><div class=\"kurss-example\">Der Eimer ist voll. Die Eimer sind voll.</div><div class=\"kurss-example\">Der Teller ist leer. Die Teller sind leer.</div><div class=\"kurss-example\">Der Wagen ist schwer. Die Wagen sind schwer.</div><div class=\"kurss-example\">Der Schlitten ist leicht. Die Schlitten sind leicht.</div></div></div>\n    </details>\n\n    <details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Orð</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">liegt — er, liggur</div><div class=\"kurss-example\">der Bleistift (blæsjtift) — blýanturinn</div><div class=\"kurss-example\">einige (ænige) — nokkrir</div><div class=\"kurss-example\">hinlegen — leggja frá sér</div><div class=\"kurss-example\">legt hin — leggur frá sér</div><div class=\"kurss-example\">wieder (víder) — aftur</div><div class=\"kurss-example\">aufmachen — opna</div><div class=\"kurss-example\">er macht auf — hann opnar</div><div class=\"kurss-example\">anspitzen (ansjpitsen) — ydda</div><div class=\"kurss-example\">er spitzt an — hann yddar</div><div class=\"kurss-example\">sich setzen — setjast</div><div class=\"kurss-example\">setzt sich — sest</div><div class=\"kurss-example\">der Schlüssel (sjlussel) — lykillinn</div><div class=\"kurss-example\">das Fenster (fenster) — glugginn</div><div class=\"kurss-example\">die Tafel (dí tafel) — taflan</div><div class=\"kurss-example\">der Garten — garðurinn</div><div class=\"kurss-example\">der Löffel — skeiðin</div><div class=\"kurss-example\">zählen (tselen) — telja</div><div class=\"kurss-example\">die Nadel — nálin</div><div class=\"kurss-example\">was ist das — hvað er þetta?</div><div class=\"kurss-example\">der Hammer — hamarinn</div><div class=\"kurss-example\">die Hämmer — hamrarnir</div><div class=\"kurss-example\">der Deckel (der dekel) — lokið</div><div class=\"kurss-example\">der Teller — diskurinn</div><div class=\"kurss-example\">der Wagen — vagninn</div><div class=\"kurss-example\">der Schlitten — sleðinn</div><div class=\"kurss-example\">das Ding — hluturinn</div><div class=\"kurss-example\">die Dinge — hlutirnir</div><div class=\"kurss-example\">wie sind die Dinge? — hvernig eru hlutirnir?</div><div class=\"kurss-example\">voll (fol) — fullur</div><div class=\"kurss-example\">leer (ler) — tómur</div><div class=\"kurss-example\">schwer (sjver) — þungur, erfiður</div><div class=\"kurss-example\">leicht — léttur</div><div class=\"kurss-example\">der Eimer — fatan</div><div class=\"kurss-example\">wieviel (vífíl) — hve margir</div><div class=\"kurss-example\">wieviel Nadeln — hve margar nálar</div><div class=\"kurss-example\">hier (hír) — hér</div><div class=\"kurss-example\">dort — þar</div></div></div>\n    </details>\n\n    <details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Framburður</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ä er hljóðvarp sérhljóðsins a og er borið fram eins og stutt eða langt e.</div><div class=\"kurss-example\">Dæmi: das Mädchen (medhjen), die Bänke (dí benke), der Vater (der fater), die Väter (dí feter).</div><div class=\"kurss-example\">ü er hljóðvarp sérhljóðsins u. Til að bera það fram þarf að setja varirnar vel í stút og reyna að segja i með kringdum vörum.</div><div class=\"kurss-example\">Dæmi: fünf, der Schlüssel (sjlussel).</div><div class=\"kurss-example\">ö er borið fram með kringdum vörum um leið og reynt er að segja e: der Löffel.</div><div class=\"kurss-example\">Tvöfaldur sérhljóði táknar langt sérhljóð: leer (ler).</div><div class=\"kurss-example\">Tvíhljóðið eu er borið fram sem oj: neun (nojn).</div></div></div>\n    </details>\n\n    <details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Málfræði</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content lesson1-grammar-content\">\n        <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">Málfræði og skýringar</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Áherslubundið forskeyti samsettrar sagnar losnar frá sögninni í nútíð og stendur aftast í setningunni.</div><div class=\"kurss-example\">Dæmi: hinlegen — er legt hin; aufmachen — er macht auf; anspitzen — er spitzt an.</div><div class=\"kurss-example\">Töluorðið einn hefur sérstakt form í hverju kyni þegar það er notað með nafnorði: í karlkyni ein, í kvenkyni eine, í hvorugkyni ein.</div><div class=\"kurss-example\">Dæmi: ein Schüler — einn nemandi; eine Schülerin — ein skólastúlka; ein Kind — eitt barn.</div><div class=\"kurss-example\">Tölur: eins, zwei, drei, vier (fír), fünf, sechs (seks), sieben (síben), acht, neun (nojn), zehn (tsen).</div><div class=\"kurss-example\">Tengisögnin hefur í þýsku eintölu- og fleirtölumynd: der Schüler ist klein; die Schüler sind klein.</div><div class=\"kurss-example\">Í setningum eins og „þetta er …“ er ábendingarfornafnið þetta í íslensku óbreytt, og eins er í þýsku aðeins notað eitt form: das.</div><div class=\"kurss-example\">Dæmi: þetta er hamar — das ist ein Hammer; þetta er nál — das ist eine Nadel; þetta eru hamrar — das sind Hämmer; þetta eru nálar — das sind Nadeln.</div><div class=\"kurss-example\">Der Wagen — vagn og der Schlitten — sleði eru í þýsku notuð bæði í eintölu og fleirtölu, eins og í íslensku.</div><div class=\"kurss-example\">Karlkyns- og hvorugkynsnafnorð með endingunni -er, -el, -en fá oft enga endingu í fleirtölu.</div><div class=\"kurss-example\">Dæmi: der Hammer — die Hämmer; der Garten — die Gärten; das Fenster — die Fenster; das Messer — die Messer.</div><div class=\"kurss-example\">Kvenkynsnafnorð með endingunni -el, -er fá -n í fleirtölu.</div><div class=\"kurss-example\">Dæmi: die Nadel — die Nadeln; die Feder — die Federn.</div><div class=\"kurss-example\">Undantekningar: die Mutter (móðir) — die Mütter (mæður); die Tochter (dóttir) — die Töchter (dætur).</div><div class=\"kurss-example\">Óákveðni greinirinn hefur enga fleirtölu: das ist ein Wagen — das sind Wagen; das ist eine Nadel — das sind Nadeln.</div><div class=\"kurss-example\">Í fullyrðingarsetningu stendur sögnin, sem er umsögn, í öðru sæti: er legt den Schlüssel hin; dann legt er den Schlüssel hin.</div></div></section>\n      </div>\n    </details>\n\n    <details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Þýddu</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-training-wrap\"><button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson6-training-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"Kennslustund 6: þýðingarspjald\"><span class=\"lesson1-training-progress\">Kennslustund 6 · Þýddu: 1 / 21</span><span class=\"lesson1-training-text\">Paul tekur blýant og teiknar.</span></button><p class=\"lesson1-training-hint\">Smelltu á spjaldið til að sjá þýsku þýðinguna. Eftir svarið sýnir næsti smellur næsta spjald.</p></div></div>\n    </details>\n  ",
  "kurssLesson7": "            <h3>Kennslustund 7</h3>\n            <p class=\"kurss-lesson-intro\">Sjöunda kennslustund: boðháttur, kurteisisávarp og fleirtala.</p>\n            <details class=\"lesson1-accordion\" open>\n              <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Samtöl / setningar</span><span class=\"lesson1-chevron\">⌃</span></summary>\n              <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Hans, singe ein Lied! Was tust du? Ich singe ein Lied.</div><div class=\"kurss-example\">Hans und Olga, singt ein Lied! Was tut ihr? Wir singen ein Lied.</div><div class=\"kurss-example\">Fräulein Müller, singen Sie, bitte, ein Lied! Was tun Sie? Ich singe ein Lied.</div><div class=\"kurss-example\">Hans, zähle die Teller! Was tut Hans? Er zählt die Teller.</div><div class=\"kurss-example\">Hans und Olga, zählt die Teller! Was tun Hans und Olga? Sie zählen die Teller.</div><div class=\"kurss-example\">Fräulein Müller, zählen Sie, bitte, die Teller!</div><div class=\"kurss-example\">Hans, öffne das Fenster! Was tut Hans? Er öffnet das Fenster.</div><div class=\"kurss-example\">Hans und Olga, öffnet die Fenster! Was tun Hans und Olga? Sie öffnen die Fenster.</div><div class=\"kurss-example\">Fräulein Müller, öffnen Sie, bitte, alle Fenster!</div><div class=\"kurss-example\">Fräulein Müller öffnet alle Fenster.</div><div class=\"kurss-example\">Das ist der Spiegel. Das sind die Spiegel.</div><div class=\"kurss-example\">Das ist der Lappen. Das sind die Lappen.</div><div class=\"kurss-example\">Das ist der Spaten. Das sind die Spaten.</div><div class=\"kurss-example\">Das ist der Besen. Das sind die Besen.</div><div class=\"kurss-example\">Das ist die Schaufel. Das sind die Schaufeln.</div><div class=\"kurss-example\">Das ist die Schüssel. Das sind die Schüsseln.</div><div class=\"kurss-example\">Das ist das Zimmer. Das sind die Zimmer.</div><div class=\"kurss-example\">Das ist das Ufer. Das sind die Ufer.</div></div></div>\n            </details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Orð</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">singen — syngja</div><div class=\"kurss-example\">singe — syngdu</div><div class=\"kurss-example\">singt — syngið</div><div class=\"kurss-example\">singen Sie — syngið (kurteisisform)</div><div class=\"kurss-example\">das Lied (das lít) — lagið, söngurinn</div><div class=\"kurss-example\">Sie — þér (kurteisisform)</div><div class=\"kurss-example\">zählen — telja</div><div class=\"kurss-example\">das Fräulein (frojlæn) — ungfrúin</div><div class=\"kurss-example\">der Müller — malarinn</div><div class=\"kurss-example\">öffnen — opna</div><div class=\"kurss-example\">das Fenster (fenster) — glugginn</div><div class=\"kurss-example\">alle — allir</div><div class=\"kurss-example\">der Spiegel (sjpígel) — spegillinn</div><div class=\"kurss-example\">der Lappen — tuskan, klúturinn</div><div class=\"kurss-example\">der Spaten — stunguskóflan</div><div class=\"kurss-example\">der Besen — kústurinn</div><div class=\"kurss-example\">die Schaufel — litla skóflan</div><div class=\"kurss-example\">die Schüssel — skálin</div><div class=\"kurss-example\">das Zimmer — herbergið</div><div class=\"kurss-example\">das Ufer (úfer) — bakkinn, ströndin</div></div></div></details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Framburður</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">sp í upphafi orðs eða atkvæðis er borið fram sem sjp: der Spiegel (der sjpígel).</div><div class=\"kurss-example\">sch er borið fram líkt og sj í íslenska orðinu sjór: die Schaufel (dí sjáfel), die Schüssel (dí sjussel).</div><div class=\"kurss-example\">Tvíhljóðið äu er borið fram eins og oj í íslensku upphrópuninni oj: das Fräulein (das frojlæn).</div></div></div></details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Málfræði</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content lesson1-grammar-content\"><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>1</span>Boðháttur</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Boðháttur í 2. persónu eintölu samsvarar 2. persónu eintölu sagnarinnar án persónuendingarinnar -st, en bætt er við endingunni -e.</div><div class=\"kurss-example\">Dæmi: antworte!, arbeite!, öffne!, zeichne!</div><div class=\"kurss-example\">Mjög oft er endingunni -e sleppt ef boðhátturinn er einsatkvæðis án hennar: geh!, steh!, komm!, tu!, sing!, frag!</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>2</span>Boðháttur í fleirtölu</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Boðháttur í 2. persónu fleirtölu er eins og 2. persóna fleirtölu í nútíð, en hann er notaður án fornafns.</div><div class=\"kurss-example\">Dæmi: antwortet!, arbeitet!, öffnet!, zeichnet!, geht!, steht!, tut!</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>3</span>Kurteisisávarp með Sie</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Kurteisisávarpið „þér“ samsvarar í þýsku 3. persónu fleirtölu. Fornafnið Sie er skrifað með stórum staf og stendur á eftir sögninni.</div><div class=\"kurss-example\">Dæmi: antworten Sie!, arbeiten Sie!, öffnen Sie!, zeichnen Sie!, gehen Sie!, stehen Sie!, tun Sie!</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>4</span>öffnen</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Í sögninni öffnen er e skotið inn á milli stofns og endingar í 2. og 3. persónu eintölu og 2. persónu fleirtölu til að auðvelda framburð: du öffnest, er öffnet, ihr öffnet.</div></div></section></div></details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Übung / Æfing</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-training-wrap\"><button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson7-exercise-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"Kennslustund 7: æfingaspjald\"><span class=\"lesson1-training-progress\">Kennslustund 7 · Übung: 1 / 16</span><span class=\"lesson1-training-text\">fragen — spyrja</span></button><p class=\"lesson1-training-hint\">Snertu spjaldið til að sjá boðháttarmyndirnar.</p></div></div></details>"
};

